#!/usr/bin/env node
// Runs the prebuilt secrets-anything binary for this platform (installed as an optional dependency).
// Generated by anything-anything.
"use strict";
const { spawnSync } = require("node:child_process");
const fs = require("node:fs");

const pkg = `@el4cteo/secrets-anything-${process.platform}-${process.arch}`;
const exe = process.platform === "win32" ? "secrets-anything.exe" : "secrets-anything";
let bin;
try {
  bin = require.resolve(`${pkg}/bin/${exe}`);
} catch {
  console.error(
    `secrets-anything: no prebuilt binary for ${process.platform}-${process.arch} (${pkg} isn't installed).\n` +
      "Reinstall without --omit=optional, or build it: cargo install secrets-anything",
  );
  process.exit(1);
}
if (process.platform !== "win32") {
  try {
    fs.chmodSync(bin, 0o755);
  } catch {
    // spawnSync reports EACCES if it still isn't executable
  }
}
const run = spawnSync(bin, process.argv.slice(2), { stdio: "inherit" });
if (run.error) {
  console.error(`secrets-anything: ${run.error.message}`);
  process.exit(1);
}
process.exit(run.status ?? 1);
